// in ParseFileStats:  name := headerName(l)
func headerName(l string) string {
	if strings.HasSuffix(l, `"`) {
		if i := strings.LastIndex(l, ` "b/`); i >= 0 {
			if s, err := strconv.Unquote(l[i+1:]); err == nil {
				return strings.TrimPrefix(s, "b/")
			}
		}
	}
	return l[strings.LastIndex(l, " b/")+3:]
}
